/*
 * network_$page_chksum - Checksum the first data page of a packet
 *
 * Original address: 0x00E0F312, 104 bytes (0x00E0F312 .. 0x00E0F379); the
 * SAU2 map names it GET_CHKSUM, a module-local (no `$`) NETWORK routine.
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,-0x10; D2/A2/A3 saved):
 *   (0x08,A6) data_bufs  -> longword, the data buffer's physical address
 *   (-0x04,A6) va        (-0x08,A6) status
 *
 * Maps the buffer with NETBUF_$GETVA (a failure crashes the system with the
 * status), sums the page with NETWORK_$GET_CHKSUM, unmaps it with
 * NETBUF_$RTNVA and clears the frame's used bit with MMU_$CLR_USED.
 *
 * Callers pass a second argument (NETWORK_$READ_AHEAD `pea (-0x14e,A6)` at
 * 0x00E0FED8 before `pea (-0x10,A6)`, cleaned with `addq.w #8`); the
 * routine never reads (0xC,A6).
 */

#include "network/network_internal.h"
#include "netbuf/netbuf.h"
#include "mmu/mmu.h"
#include "misc/crash_system.h"

uint32_t network_$page_chksum(uint32_t *data_bufs)
{
    uint32_t va;          /* (-0x4,A6), A2 */
    status_$t status;     /* (-0x8,A6) */
    uint32_t sum;         /* D2 */

    NETBUF_$GETVA(*data_bufs, &va, &status);        /* 0x00E0F328 */
    if (status != status_$ok) {
        CRASH_SYSTEM(&status);                      /* 0x00E0F340 */
    }
    sum = NETWORK_$GET_CHKSUM(va);                  /* 0x00E0F34A */
    NETBUF_$RTNVA(&va);                             /* 0x00E0F358 */
    MMU_$CLR_USED(*data_bufs >> 10);                /* 0x00E0F368 */
    return sum;
}
